const tabId = 886078847;
const res = await browserjs(tabId, () => {
  // Let's find Leaflet map or React/Vue state
  const mapEl = document.querySelector('.leaflet-container');
  if (!mapEl) return "No leaflet container";
  // Leaflet usually attaches _leaflet_id or map instance
  let mapObj = null;
  for (const key in mapEl) {
    if (key.startsWith('_leaflet_map') || key === '_leaflet_events') {
      mapObj = mapEl[key];
    }
  }
  // Let's see if there's any window property or leaflet markers with data
  const markers = document.querySelectorAll('.leaflet-marker-icon');
  const sampleMarker = markers[0];
  let markerProps = [];
  for (const k in sampleMarker) {
    if (k.startsWith('__react') || k.startsWith('_leaflet')) {
      markerProps.push(k);
    }
  }

  // Also check performance entries for fetch URLs
  const fetches = performance.getEntriesByType('resource')
    .filter(r => r.initiatorType === 'fetch' || r.initiatorType === 'xmlhttprequest')
    .map(r => r.name);

  return { markerProps, fetches };
});
console.log(res);

