const tabId = 886078847;
const results = await browserjs(tabId, async () => {
  const resp = await fetch("https://tjalda.is/api/campsites");
  const campsites = await resp.json();

  // Filter for South Iceland and Capital/Reykjanes
  const southCampgrounds = campsites
    .filter(c => c.region && (c.region.slug === "sudurland" || c.region.slug === "sudurnes" || c.region.slug === "hofudborgarsvaedid"))
    .map(c => ({
      name: c.name,
      slug: c.slug,
      city: c.city,
      lat: c.latitude,
      lng: c.longitude,
      region: c.region.name_en,
      season_open: c.opening_time_custom_text_en || c.opening_time,
      prices: c.prices_en ? c.prices_en.slice(0, 100) : "N/A",
      services: c.services ? c.services.map(s => s.title_en) : []
    }));
  return southCampgrounds;
});
console.log("Total south/capital campsites:", results.length);
console.log("Sample names & slugs:", results.map(r => `${r.name} (${r.slug})`));

